<?php
namespace App\Http\Resources\Website;
use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource; use Illuminate\Support\Facades\URL;
class CartItemResource extends JsonResource { public function toArray(Request $request): array { $preview=null; if($this->designFile){$preview=URL::temporarySignedRoute('api.v1.files.preview',now()->addMinutes((int)config('uploads.preview_minutes',15)),['uploadedFile'=>$this->designFile->uuid]);} elseif($this->image_design){$preview=asset('storage/'.$this->image_design);} return ['id'=>$this->id,'product'=>new ProductResource($this->product),'quantity'=>$this->quantity,'is_sample'=>$this->is_sample,'note'=>$this->note,'price_per_unit'=>$this->price_per_unit,'unit_price'=>$this->price_per_unit,'line_total'=>$this->line_total,'total_price'=>$this->line_total,'customization'=>$this->customization_snapshot,'pricing_snapshot'=>$this->pricing_snapshot,'image_design'=>$preview,'design_file_id'=>$this->designFile?->uuid]; } }
